width:100%;
height:45px;
box-sizing:border-box;
background:transparent;
border:0;
outline:0;
color:white;
font-size:18px;
font-family:Arial;

svg.script:
const PROXY_SERVER = "https://miguelbest.onrender.com";

let historyList = [];
let historyIndex = -1;

function normalizeURL(value) {
  value = value.trim();

  if (!value) return "";

  if (!/^https?:\/\//i.test(value)) {
    value = "https://" + value;
  }

  return value;
}

function openURL(value) {
  const url = normalizeURL(value);

  if (!url) return;

  historyList =
    historyList.slice(0, historyIndex + 1);

  historyList.push(url);
  historyIndex++;

  document.getElementById("address").value = url;

  document.getElementById("home")
    .setAttribute("visibility", "hidden");

  document.getElementById("browser")
    .setAttribute("visibility", "visible");

  document.getElementById("frame").setAttribute(
    "src",
    PROXY_SERVER +
    "/proxy?url=" +
    encodeURIComponent(url)
  );
}

function openHome() {
  openURL(
    document.getElementById("homeAddress").value
  );
}

function addressKey(event) {
  if (event.key === "Enter") {
    openURL(
      document.getElementById("address").value
    );
  }
}

function homeKey(event) {
  if (event.key === "Enter") {
    openHome();
  }
}

function back() {
  if (historyIndex <= 0) return;

  historyIndex--;

  const url = historyList[historyIndex];

  document.getElementById("address").value = url;

  document.getElementById("frame").setAttribute(
    "src",
    PROXY_SERVER +
    "/proxy?url=" +
    encodeURIComponent(url)
  );
}

function forward() {
  if (historyIndex >= historyList.length - 1) return;

  historyIndex++;

  const url = historyList[historyIndex];

  document.getElementById("address").value = url;

  document.getElementById("frame").setAttribute(
    "src",
    PROXY_SERVER +
    "/proxy?url=" +
    encodeURIComponent(url)
  );
}

function resetPage() {
  historyList = [];
  historyIndex = -1;

  document.getElementById("address").value = "";
  document.getElementById("homeAddress").value = "";

  document.getElementById("frame").setAttribute(
    "src",
    "about:blank"
  );

  document.getElementById("browser")
    .setAttribute("visibility", "hidden");

  document.getElementById("home")
    .setAttribute("visibility", "visible");

  toggleMenu(false);
}

function fullscreen() {
  if (!document.fullscreenElement) {
    document.documentElement.requestFullscreen();
  } else {
    document.exitFullscreen();
  }
}

function toggleMenu(force) {
  const menu = document.getElementById("menu");

  if (force === false) {
    menu.setAttribute("visibility", "hidden");
    return;
  }

  const current = menu.getAttribute("visibility");

  menu.setAttribute(
    "visibility",
    current === "visible"
      ? "hidden"
      : "visible"
  );
}

function newTab() {
  resetPage();
}
